        JSONObject loaded=sync.optJSONObject("loaded");int rows=0;if(loaded!=null){java.util.Iterator<String> keys=loaded.keys();while(keys.hasNext())rows+=loaded.optInt(keys.next());}return (sync.optInt("resumedRecords")>0?"Yükləməyə davam edin. Əvvəllər yadda saxlanıldı: "+sync.optInt("resumedRecords")+". ":"")+"Qəbul edilən qeydlər: "+rows+". Hazır hissələr: "+(ready==null?0:ready.length())+". Gözlənilir: "+names+".";
