    private String backgroundProgressText(JSONObject sync){JSONArray pending=sync.optJSONArray("backgroundPending");JSONObject loaded=sync.optJSONObject("backgroundLoaded");StringBuilder out=new StringBuilder();if(pending!=null)for(int i=0;i<pending.length();i++){JSONObject part=pending.optJSONObject(i);if(part==null)continue;if(out.length()>0)out.append(", ");String key=part.optString("key");out.append(part.optString("part")).append(": ").append(loaded==null?0:loaded.optInt(key)).append(" qeydləri");}return out.toString();}
    private String syncErrors(JSONArray errors){if(errors==null)return "";StringBuilder out=new StringBuilder();for(int i=0;i<errors.length();i++){JSONObject error=errors.optJSONObject(i);if(error==null)continue;if(out.length()>0)out.append("; ");out.append(error.optString("part","Bölmə")).append(": ").append(OfflineNetwork.error(error.optString("error"))?"əlaqə yoxdur":error.optString("error","Oxu xətası"));}return out.toString();}
    private boolean successful(JSONObject data,String key){JSONObject sync=data.optJSONObject("sync");JSONArray parts=sync==null?null:sync.optJSONArray("successful");if(parts==null)return true;for(JSONArray list:new JSONArray[]{parts,sync.optJSONArray("available")})if(list!=null)for(int i=0;i<list.length();i++)if(key.equals(list.optString(i)))return true;return false;}
    private void applyPersonalRefreshResult(JSONObject result,boolean partial){TaskHistory.observe(result);
        try{if(partial&&!successful(result,"tasks")){result.put("tasks",personalTasks);result.put("pomodoroTasks",personalPomodoroTasks);}if(partial&&!successful(result,"containers"))result.put("containers",personalContainers);}catch(Exception ignored){}
        applyPersonalSnapshot(result);PlannerCache.rememberPersonal(this,result);
    }
    private void applyEquipmentRefreshResult(JSONObject result,boolean partial){TaskHistory.observe(result);
        if(partial)try{JSONArray freshGraph=result.optJSONArray("pomodoroTasks");if(freshGraph==null)freshGraph=new JSONArray();JSONArray combined=new JSONArray();for(int i=0;i<equipmentPomodoroTasks.length();i++){JSONObject t=equipmentPomodoroTasks.optJSONObject(i);if(t!=null&&!successful(result,t.optString("sourceKey")))combined.put(t);}for(int i=0;i<freshGraph.length();i++){JSONObject t=freshGraph.optJSONObject(i);if(t!=null&&successful(result,t.optString("sourceKey")))combined.put(t);}result.put("pomodoroTasks",combined);
            result.put("plans",mergeEquipmentCollection(result,"plans",plans,combined));result.put("equipment",mergeEquipmentCollection(result,"machines",equipment,combined));
        }catch(Exception ignored){}
        applyPlanSnapshot(result);
    }
    private JSONArray mergeEquipmentCollection(JSONObject data,String key,JSONArray old,JSONArray graph)throws Exception{
        String field=key.equals("plans")?"plans":"equipment";JSONArray received=data.optJSONArray(field);if(received==null)received=new JSONArray();JSONArray layouts=successful(data,key)?received:(old.length()>0?old:received),out=new JSONArray();
        for(int i=0;i<layouts.length();i++){JSONObject original=layouts.optJSONObject(i);if(original==null)continue;JSONObject item=new JSONObject(original.toString());String id=item.optString("id");JSONObject previous=find(old,id),fresh=find(received,id);java.util.LinkedHashMap<String,JSONObject> rows=new java.util.LinkedHashMap<>();JSONArray prior=previous==null?null:previous.optJSONArray("tasks");if(prior!=null)for(int j=0;j<prior.length();j++){JSONObject t=prior.optJSONObject(j);if(t!=null&&!successful(data,t.optString("sourceKey")))rows.put(t.optString("id"),t);}
            JSONArray next=fresh==null?null:fresh.optJSONArray("tasks");if(next!=null)for(int j=0;j<next.length();j++){JSONObject t=next.optJSONObject(j);if(t!=null&&successful(data,t.optString("sourceKey"))&&TaskHistory.visible(t))rows.put(t.optString("id"),t);}
            for(int j=0;j<graph.length();j++){JSONObject t=graph.optJSONObject(j);if(t==null||!TaskHistory.visible(t)||!successful(data,t.optString("sourceKey")))continue;boolean linked=key.equals("plans")?id.equals(t.optString("planId"))&&t.optString("machineId").isEmpty():id.equals(t.optString("machineId"));JSONArray machines=t.optJSONArray("machineIds");if(!key.equals("plans")&&machines!=null)for(int m=0;m<machines.length();m++)linked|=id.equals(machines.optString(m));if(linked)rows.put(t.optString("id"),t);}
            JSONArray tasks=new JSONArray();for(JSONObject t:rows.values())tasks.put(t);item.put("tasks",tasks);if(previous!=null&&(!successful(data,"todo")||!successful(data,"gorulen"))&&previous.has("taskCounts"))item.put("taskCounts",previous.optJSONObject("taskCounts"));out.put(item);
        }return out;
    }
    private void updateRefreshUi(){if(!queueSuffix.isEmpty()&&refreshStatus.endsWith(queueSuffix))refreshStatus=refreshStatus.substring(0,refreshStatus.length()-queueSuffix.length());queueSuffix="";boolean personal=personalRefreshScope();RefreshGroup group=refreshGroup(personal);if(personalRefresh.busy||equipmentRefresh.busy||!group.status.isEmpty()){loading=group.busy;refreshStatus=group.status;loadError=group.error;}
        String queue=OfflineDeletes.summary(this);if(!queue.isEmpty()){queueSuffix=(refreshStatus.isEmpty()?"":" · ")+queue;refreshStatus+=queueSuffix;}
        String scope=personal?"personal":"equipment";if(!scope.equals(renderedRefreshScope)){renderedRefreshScope=scope;if(!Boolean.getBoolean("adib.testing")&&group.updatedAt==0)new android.os.Handler(android.os.Looper.getMainLooper()).post(()->{if(!isFinishing()&&!group.busy&&group.updatedAt==0)refreshSection(personal,true,false);});}updateRefreshChrome();}
