    private JSONObject snapshotRequest(String path)throws Exception{if(!DirectRuntime.enabled()&&AccountSession.required&&path.startsWith("/api/plan-snapshot")&&!AccountSession.section("equipment"))return new JSONObject().put("ok",true).put("plans",new JSONArray()).put("equipment",new JSONArray()).put("pomodoroTasks",new JSONArray());
        if(Boolean.getBoolean("adib.testing"))return null;if(!OfflineNetwork.available(this))throw new java.io.IOException("Bağlantı yoxdur");if(DirectRuntime.enabled())return DirectRuntime.request("GET",path,null);
        HttpURLConnection connection=null;try{String base=BuildConfig.APP_BASE_URL;connection=(HttpURLConnection)new URL((base.endsWith("/")?base.substring(0,base.length()-1):base)+path).openConnection();AccountSession.authorize(connection);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("Accept","application/json");int status=AccountSession.response(connection);InputStream input=status>=400?connection.getErrorStream():connection.getInputStream();if(input==null)throw new java.io.IOException("HTTP "+status+": boş cavab");String text;try(InputStream in=input){text=DirectRuntime.text(in,16*1024*1024);}JSONObject answer=new JSONObject(text);if(status>=400)throw new java.io.IOException("HTTP "+status+": "+answer.optString("error","Server xətası"));return answer;}finally{if(connection!=null)connection.disconnect();}
    }

    private void applyPlanSnapshot(JSONObject data){data=TaskHistory.snapshot(OfflineDeletes.filterSnapshot(this,data));
        equipmentPomodoroTasks=data.optJSONArray("pomodoroTasks")==null?new JSONArray():data.optJSONArray("pomodoroTasks");
        plans=data.optJSONArray("plans")==null?new JSONArray():data.optJSONArray("plans");
        equipment=data.optJSONArray("equipment")==null?new JSONArray():data.optJSONArray("equipment");
        if(currentPlanId.isEmpty()){JSONObject start=findPlanByName("ADIB");if(start==null)for(int i=0;i<plans.length();i++){JSONObject candidate=plans.optJSONObject(i);if(candidate!=null&&!hasValue(candidate,"parentId")){start=candidate;break;}}if(start==null&&plans.length()>0)start=plans.optJSONObject(0);if(start!=null)currentPlanId=start.optString("id");}
    }
    private void applyPersonalSnapshot(JSONObject data){data=TaskHistory.snapshot(OfflineDeletes.filterSnapshot(this,data));
        personalPomodoroTasks=data.optJSONArray("pomodoroTasks")==null?new JSONArray():data.optJSONArray("pomodoroTasks");
        personalTasks=data.optJSONArray("tasks")==null?new JSONArray():data.optJSONArray("tasks");
        mergeConfirmedCreations();
        try{data.put("tasks",personalTasks);}catch(Exception ignored){}
        personalContainers=data.optJSONArray("containers")==null?new JSONArray():data.optJSONArray("containers");
        processPendingWidgetNavigation();
    }
    private void mergeConfirmedCreations(){
        long now=android.os.SystemClock.elapsedRealtime();
        java.util.Iterator<String> it=confirmedCreations.keySet().iterator();
        while(it.hasNext()){
            String id=it.next();
            if(OfflineDeletes.hidden(this,id)||confirmedCreations.get(id).optBoolean("completed")||find(personalTasks,id)!=null||now-confirmedCreationTimes.getOrDefault(id,0L)>120000){it.remove();confirmedCreationTimes.remove(id);}
            else personalTasks.put(confirmedCreations.get(id));
        }
    }
    private void acceptConfirmedPersonalTask(JSONObject payload,JSONObject result,boolean fresh){
        String id=result.optString("id",payload.optString("id"));if(id.isEmpty()||OfflineDeletes.hidden(this,id))return;
        try{
            JSONObject previous=find(personalTasks,id);if(previous==null)previous=find(personalPomodoroTasks,id);
            JSONObject task=new JSONObject(previous==null?"{}":previous.toString());
            java.util.Iterator<String> keys=payload.keys();while(keys.hasNext()){String key=keys.next();if(!key.equals("pageBlocks")&&!key.equals("pageContent"))task.put(key,payload.get(key));}
            JSONObject mapped=result.optJSONObject("task");if(mapped!=null){keys=mapped.keys();while(keys.hasNext()){String key=keys.next();task.put(key,mapped.get(key));}}
            if(result.has("completedAt"))task.put("completedAt",result.opt("completedAt"));if(TaskHistory.done(task)&&TaskCalendarModel.parseDateTime(task.optString("completedAt"))==null)task.put("completedAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSXXX",java.util.Locale.ROOT).format(new java.util.Date(TaskHistory.now())));JSONArray graph=new JSONArray();for(int i=0;i<personalPomodoroTasks.length();i++){JSONObject old=personalPomodoroTasks.optJSONObject(i);if(old!=null&&!id.equals(old.optString("id")))graph.put(old);}graph.put(task);personalPomodoroTasks=graph;task.put("id",id);if(result.has("estimateMinutes"))task.put("estimateMinutes",result.get("estimateMinutes"));
            JSONArray next=new JSONArray();boolean replaced=false;
            for(int i=0;i<personalTasks.length();i++){JSONObject old=personalTasks.optJSONObject(i);if(old!=null&&id.equals(old.optString("id"))){if(TaskHistory.visible(task))next.put(task);replaced=true;}else if(old!=null)next.put(old);}
            if(!replaced&&TaskHistory.visible(task))next.put(task);personalTasks=next;
            if(fresh&&!task.optBoolean("completed")){confirmedCreations.put(id,task);confirmedCreationTimes.put(id,android.os.SystemClock.elapsedRealtime());}
            else if(confirmedCreations.containsKey(id)){if(task.optBoolean("completed")){confirmedCreations.remove(id);confirmedCreationTimes.remove(id);}else confirmedCreations.put(id,task);}
            taskMutationGeneration++;
            PlannerCache.rememberPersonal(this,new JSONObject().put("tasks",personalTasks).put("containers",personalContainers));
            render();
        }catch(Exception ignored){}
    }
    private void restoreSnapshotCache(){
        try(FileInputStream in=openFileInput("adib-snapshot-cache.json")){
            JSONObject saved=new JSONObject(DirectRuntime.text(in,64*1024*1024));
            JSONObject a=saved.optJSONObject("plans"),b=saved.optJSONObject("personal");
            if(a!=null){lastGoodPlans=a;applyPlanSnapshot(a);cacheRestored=true;}if(b!=null){lastGoodPersonal=b;PlannerCache.rememberRestoredPersonal(this,b);applyPersonalSnapshot(b);cacheRestored=true;}
        }catch(Exception ignored){}
        try{String savedOptions=getPreferences(0).getString("adib-task-options","");if(!savedOptions.isEmpty())taskOptions=new JSONObject(savedOptions);}catch(Exception ignored){}
    }
    private void saveSnapshotCache(JSONObject plansData,JSONObject personalData){
        try{if(plansData!=null)lastGoodPlans=new JSONObject(plansData.toString());if(personalData!=null)lastGoodPersonal=new JSONObject(personalData.toString());JSONObject saved=new JSONObject();if(lastGoodPlans!=null)saved.put("plans",lastGoodPlans);if(lastGoodPersonal!=null)saved.put("personal",lastGoodPersonal);final String bytes=saved.toString();final long revision=++snapshotDiskRevision;
            IO.execute(()->{synchronized(snapshotDiskLock){if(revision!=snapshotDiskRevision)return;try{java.io.File temp=getFileStreamPath("adib-snapshot-cache.json.tmp");try(java.io.FileOutputStream out=new java.io.FileOutputStream(temp)){out.write(bytes.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!temp.renameTo(getFileStreamPath("adib-snapshot-cache.json")))throw new java.io.IOException("Keşi yadda saxlamaq alınmadı");}catch(Exception ignored){}}});
        }catch(Exception ignored){}
    }

    private JSONObject request(String method,String path,JSONObject payload){return requestWithTimeout(method,path,payload,240000);}
    private JSONObject requestWithTimeout(String method, String path, JSONObject payload,int readTimeout) {
        HttpURLConnection c = null;
        try {
            if(!DirectRuntime.enabled()&&path.equals("/api/personal-pomodoro"))return PomodoroRpc.request(MainActivity.this,method,path,payload,readTimeout);if(DirectRuntime.enabled())return DirectRuntime.request(method,path,payload);
            String base = BuildConfig.APP_BASE_URL;
            URL u = new URL(base.endsWith("/") ? base.substring(0, base.length()-1) + path : base + path);
            c = (HttpURLConnection) u.openConnection();AccountSession.authorize(c); c.setRequestMethod(method); c.setConnectTimeout(Math.min(30000,readTimeout)); c.setReadTimeout(readTimeout); c.setRequestProperty("Accept", "application/json");
            if (payload != null) { c.setDoOutput(true); c.setRequestProperty("Content-Type", "application/json; charset=utf-8"); try (OutputStream out=c.getOutputStream()) { out.write(payload.toString().getBytes(StandardCharsets.UTF_8)); } }
            int status=AccountSession.response(c); InputStream in=status>=400?c.getErrorStream():c.getInputStream(); if(in==null)return new JSONObject();
            StringBuilder s=new StringBuilder(); try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null)s.append(line);}
            JSONObject result=new JSONObject(s.toString()); if(status>=400) throw new RuntimeException(result.optString("error","HTTP "+status)); return result;
        } catch(Exception e) { final String m=e.getMessage()==null?"Şəbəkə xətası":e.getMessage(); runOnUiThread(()->{ if(!m.isEmpty()) { /* shown by caller or refresh */ } }); return null; }
        finally { if(c!=null)c.disconnect(); }
    }

    private void send(String method, String path, JSONObject payload, java.util.function.Consumer<JSONObject> success) {
        IO.execute(() -> {
            JSONObject result=request(method,path,payload);
            runOnUiThread(() -> { if(result==null){toast("Yadda saxlamaq alınmadı. ilə əlaqəni yoxlayın ADIB.");return;} success.accept(result); });
        });
    }

