    private void mergePendingTasks(){personalTasks=PendingTasks.merge(this,personalTasks,"/api/personal-task");JSONArray local=PendingTasks.rows(this,"/api/task");for(JSONArray owners:new JSONArray[]{equipment,plans})for(int i=0;i<owners.length();i++){JSONObject owner=owners.optJSONObject(i);if(owner==null)continue;JSONArray clean=new JSONArray(),old=owner.optJSONArray("tasks");java.util.HashSet<String> ids=new java.util.HashSet<>();if(old!=null)for(int j=0;j<old.length();j++){JSONObject t=old.optJSONObject(j);if(t!=null&&!PendingTasks.pending(t)&&ids.add(t.optString("id")))clean.put(t);}for(int j=0;j<local.length();j++){JSONObject t=local.optJSONObject(j);String ownerId=t.optString("machineId").isEmpty()?t.optString("planId"):t.optString("machineId");if(owner.optString("id").equals(ownerId)&&ids.add(t.optString("id")))clean.put(t);}try{owner.put("tasks",clean);}catch(Exception ignored){}}equipmentPomodoroTasks=PendingTasks.merge(this,equipmentPomodoroTasks,"/api/task");if(listScopeTasks!=null)listScopeTasks=resolveTaskListScope();}
