    private void showDesignDrawer(){android.app.Dialog d=new android.app.Dialog(uiContext());ScrollView scroll=new ScrollView(this);LinearLayout menu=new LinearLayout(this);menu.setOrientation(1);menu.setPadding(dp(18),dp(24),dp(18),dp(24));menu.setBackgroundColor(panel());JSONObject u=AccountSession.user;TextView who=text(u==null?"ADIB":u.optString("name","ADIB"),21,true);who.setPadding(dp(12),dp(8),dp(12),dp(20));menu.addView(who);drawerItem(menu,d,"Tapşırıqlarım","tasks","personal",()->openHome());drawerItem(menu,d,"Gün planı","tasks","day",()->openTaskManagement("day"));drawerItem(menu,d,"Təqvim","calendar","calendar",()->openCalendar());drawerItem(menu,d,"Avadanlıq","equipment","equipment",()->openEquipment());drawerItem(menu,d,"Matris","matrix","matrix",()->{push();mode="matrix";screen="list";render();});drawerItem(menu,d,"Taymer","timer","equipment",()->showTimerHub());drawerItem(menu,d,"Söhbətlər","tasks","chat",()->showChat());TextView cap=text("QOVLUQLAR",11,true);cap.setTextColor(muted());cap.setPadding(dp(12),dp(20),0,dp(8));menu.addView(cap);if(AccountSession.section("personal"))for(int i=0;i<personalContainers.length();i++){JSONObject c=personalContainers.optJSONObject(i);if(c==null)continue;drawerItem(menu,d,c.optString("name","Qovluq"),"tasks","personal",()->{homeContainerId=c.optString("id");openHome();});}Button settings=button("Ayarlar",Color.TRANSPARENT,muted());settings.setOnClickListener(v->{d.dismiss();showSettings();});menu.addView(settings);scroll.addView(menu);d.setContentView(scroll);if(d.getWindow()!=null){d.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(panel()));d.getWindow().setGravity(Gravity.LEFT|Gravity.TOP);d.getWindow().setLayout(Math.min(dp(340),getResources().getDisplayMetrics().widthPixels-dp(36)),-1);}d.show();if(d.getWindow()!=null)d.getWindow().setLayout(Math.min(dp(340),getResources().getDisplayMetrics().widthPixels-dp(36)),-1);}
