    private void showTimerHub(){String[] labels={"İş taymeri","Pomodoro"};dialogBuilder().setTitle("Taymer").setItems(labels,(dialog,index)->{if(index==0){JSONObject own=WorkTimerClient.own(this);if(own!=null){startActivity(new Intent(this,WorkTimerActivity.class));return;}WorkTimerClient.refreshFresh(this,(state,error)->{if(state==null){toast(error);return;}JSONArray tasks=state.optJSONArray("tasks");ArrayList<JSONObject> choices=new ArrayList<>();if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t!=null&&!t.optBoolean("completed"))choices.add(t);}if(choices.isEmpty()){toast("İş taymeri üçün tapşırıq yoxdur");return;}String[] names=new String[choices.size()];for(int i=0;i<names.length;i++)names[i]=choices.get(i).optString("title","Tapşırıq");dialogBuilder().setTitle("İş üçün tapşırıq seçin").setItems(names,(d,z)->WorkTimerClient.start(this,choices.get(z))).show();});}else{ArrayList<JSONObject> choices=sortedTaskItems(personalTasks);if(choices.isEmpty()){toast("Tapşırıq yoxdur");return;}String[] names=new String[choices.size()];for(int i=0;i<names.length;i++)names[i]=choices.get(i).optString("title","Tapşırıq");dialogBuilder().setTitle("Pomodoro üçün tapşırıq seçin").setItems(names,(d,z)->openTaskForm(choices.get(z),false)).show();}}).show();}

    private void renderHome(){int oldY=homeScroll==null?0:homeScroll.getScrollY();boolean focused=homeSearch!=null&&homeSearch.hasFocus();root=new LinearLayout(this);root.setTag("adib-home");root.setOrientation(LinearLayout.VERTICAL);root.setFitsSystemWindows(true);root.setBackgroundColor(bg());root.setPadding(dp(12),0,dp(12),0);setContentView(root);toolbar=new LinearLayout(this);toolbar.setOrientation(LinearLayout.VERTICAL);toolbar.setTag("compact-view-toolbar");toolbar.setPadding(dp(4),0,dp(4),dp(2));root.addView(toolbar);
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);Button avatar=designIcon("menu","Bölmələr");head.addView(avatar,new LinearLayout.LayoutParams(dp(44),dp(44)));avatar.setOnClickListener(v->showDesignDrawer());titleView=text(homeContainerId.isEmpty()?"Tapşırıqlarım":findName(personalContainers,homeContainerId),20,true);titleView.setSingleLine(true);titleView.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(0,-2,1);hp.leftMargin=dp(10);head.addView(titleView,hp);Button more=iconButton("⋯");more.setContentDescription("Bölmələr və parametrlər");head.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));more.setOnClickListener(v->showDesignActions(v));Button homeFind=designIcon("search","Axtarış");head.addView(homeFind,new LinearLayout.LayoutParams(dp(44),dp(48)));homeFind.setOnClickListener(v->{homeSearch.setVisibility(homeSearch.getVisibility()==View.GONE?View.VISIBLE:View.GONE);if(homeSearch.getVisibility()==View.VISIBLE)homeSearch.requestFocus();});toolbar.addView(head);
        LinearLayout feedback=new LinearLayout(this);feedback.setTag("snapshot-refresh-row");feedback.setGravity(Gravity.CENTER_VERTICAL);TextView sync=text(refreshStatus.isEmpty()?"Saxlanan tapşırıqlar · arxa plan yeniləməsi":refreshStatus,12,false);sync.setTag("snapshot-refresh-status");sync.setTextColor(!loadError.isEmpty()?Color.rgb(205,60,60):muted());sync.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);feedback.addView(sync,new LinearLayout.LayoutParams(0,-2,1));Button update=iconButton(loading?"…":"⟳");update.setTag("home-refresh");update.setEnabled(!loading);update.setContentDescription(loading?"Yenilənir":"Tapşırıqları yeniləyin");feedback.addView(update,new LinearLayout.LayoutParams(dp(48),dp(48)));update.setOnClickListener(v->refresh(false));update.setOnLongClickListener(v->{dialogBuilder().setTitle("Tam uzlaşma").setMessage("Bütün bölməni yenidən oxuyun Tapşırıqlarım?").setPositiveButton("Yoxlayın",(d,w)->refreshSection(true,false,true)).setNegativeButton("Ləğv et",null).show();return true;});feedback.setVisibility(loading||!loadError.isEmpty()?View.VISIBLE:View.GONE);toolbar.addView(feedback);
        homeSearch=new EditText(uiContext());homeSearch.setTag("home-search");homeSearch.setSingleLine(true);homeSearch.setHint("Tapşırıqları axtarın…");homeSearch.setContentDescription("Tapşırıqları axtarın");HybridUi.edit(homeSearch,dark,false);homeSearch.setText(homeQuery);homeSearch.setVisibility(homeQuery.isEmpty()?View.GONE:View.VISIBLE);toolbar.addView(homeSearch,new LinearLayout.LayoutParams(-1,dp(48)));
        HorizontalScrollView chips=new HorizontalScrollView(this);chips.setHorizontalScrollBarEnabled(false);LinearLayout choices=new LinearLayout(this);choices.setGravity(Gravity.CENTER_VERTICAL);chips.addView(choices);homeChip(choices,"Hamısı","",homeContainerId.isEmpty());for(int i=0;i<personalContainers.length();i++){JSONObject c=personalContainers.optJSONObject(i);if(c!=null)homeChip(choices,c.optString("name","Qovluq"),c.optString("id"),homeContainerId.equals(c.optString("id")));}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(54));cp.topMargin=dp(8);chips.setVisibility(View.GONE);toolbar.addView(chips,cp);
        LinearLayout tools=new LinearLayout(this);tools.setGravity(Gravity.CENTER_VERTICAL);String container=homeContainerId.isEmpty()?"Bütün tapşırıqlar":findName(personalContainers,homeContainerId);TextView heading=text(container,14,true);tools.addView(heading,new LinearLayout.LayoutParams(0,-2,1));Button sort=button("Sıralama",Color.TRANSPARENT,muted());sort.setTextSize(12);sort.setContentDescription("Tapşırıqları çeşidləyin");tools.addView(sort);sort.setOnClickListener(v->showTaskSortMenu());Button filters=toolbarGlyphButton("Tapşırıq filtri","filter");tools.addView(filters,new LinearLayout.LayoutParams(dp(48),dp(48)));filters.setOnClickListener(v->showFilter());tools.setVisibility(View.GONE);toolbar.addView(tools);
        body=new FrameLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));homeScroll=new ScrollView(this);homeScroll.setFillViewport(true);homeList=new LinearLayout(this);homeList.setOrientation(LinearLayout.VERTICAL);homeList.setPadding(0,dp(4),0,dp(76));homeScroll.addView(homeList);body.addView(homeScroll,new FrameLayout.LayoutParams(-1,-1));Button plus=CompactDesign.fab(this,dark);plus.setTag("home-add");plus.setContentDescription("Tapşırığı tez əlavə edin");FrameLayout.LayoutParams fab=new FrameLayout.LayoutParams(dp(56),dp(56),Gravity.BOTTOM|Gravity.RIGHT);fab.leftMargin=dp(4);fab.rightMargin=dp(12);fab.bottomMargin=dp(12);body.addView(plus,fab);plus.setOnClickListener(v->showPlusQuickAdd());renderHomeTasks();homeSearch.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence t,int start,int count,int after){}public void onTextChanged(CharSequence t,int start,int before,int count){homeQuery=t.toString();rememberDisplayFilters();renderHomeTasks();}public void afterTextChanged(android.text.Editable e){}});appendHomeNav(true);homeScroll.post(()->homeScroll.scrollTo(0,oldY));if(focused){homeSearch.requestFocus();homeSearch.setSelection(homeSearch.length());}}
    private void appendTaskFab(){if(!AccountSession.section(mode.equals("equipment")?"equipment":"personal"))return;Button add=CompactDesign.fab(this,dark);add.setTag("task-view-add");FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(56),dp(56),Gravity.BOTTOM|Gravity.RIGHT);lp.setMargins(0,0,dp(12),dp(12));body.addView(add,lp);add.setOnClickListener(v->{if(mode.equals("matrix")){mode="personal";openTaskForm(null,true);}else if(mode.equals("personal")){if(activeBoard!=null)personalContainerId=activeBoard.optString("id");if("personal".equals(personalContainerId)||"task-list".equals(personalContainerId))personalContainerId="";openTaskForm(null,true);}else{if(activeBoard!=null&&currentMachineId.isEmpty()&&currentPlanId.isEmpty())currentMachineId=activeBoard.optString("id");openTaskForm(null,true);}});}
    private void homeChip(LinearLayout host,String name,String id,boolean active){Button chip=button(name,active?HybridUi.outgoing(dark):Color.TRANSPARENT,active?BLUE:muted());chip.setBackground(round(active?HybridUi.outgoing(dark):Color.TRANSPARENT,22,0,0));chip.setTextSize(13);chip.setTag("home-container:"+id);chip.setContentDescription("Konteyner: "+name);chip.setPadding(dp(14),0,dp(14),0);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(46));p.rightMargin=dp(8);host.addView(chip,p);chip.setOnClickListener(v->{homeContainerId=id;rememberDisplayFilters();render();});}
    private void renderHomeTasks(){if(homeList==null)return;homeList.removeAllViews();taskListPomodoroViews.clear();JSONArray candidates=new JSONArray();String query=normalizeSearch(homeQuery);for(int i=0;i<personalTasks.length();i++){JSONObject t=personalTasks.optJSONObject(i);if(!visiblePersonalRoot(t)||!matches(t))continue;if(!homeContainerId.isEmpty()&&!homeContainerId.equals(t.optString("containerId","")))continue;if(!query.isEmpty()&&!searchableText(t).contains(query))continue;candidates.put(t);}CompactDesign.Groups homeGroups=new CompactDesign.Groups(homeList,dark);for(JSONObject task:sortedTaskItems(candidates)){String id=task.optString("id");LinearLayout row=new LinearLayout(this);row.setTag("home-task:"+id);row.setGravity(Gravity.TOP);row.setPadding(0,dp(12),dp(8),dp(12));row.setBackground(round(panel(),18,Color.TRANSPARENT,0));Button check=CompactDesign.check(this,listTaskDone(task),dark);check.setPadding(0,0,0,0);check.setMinWidth(0);check.setMinimumWidth(0);check.setTextSize(24);check.setContentDescription(listTaskDone(task)?"Tapşırığı işə qaytarın":"Tamamlandı");row.addView(check,new LinearLayout.LayoutParams(dp(44),dp(44)));check.setOnClickListener(v->moveTaskToStatus(task,listTaskDone(task)?"Not started":"Done",true));LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(4),dp(8),0,0);row.addView(content,new LinearLayout.LayoutParams(0,-2,1));TextView name=text(task.optString("title","Adsız"),17,false);name.setTextColor(listTaskDone(task)?(dark?0xffa8afbc:0xff707680):fg());name.setTag("home-task-title");content.addView(name);CompactDesign.workers(content,task,dark);String due=CompactDesign.date(task);if(!due.isEmpty()){TextView date=text(due,12,false);date.setTextColor(dark?0xffa8afbc:0xff707680);date.setPadding(0,dp(6),0,0);content.addView(date);}if(PendingTasks.pending(task)){content.addView(text(task.optString("creationError").isEmpty()?"Saxlanılır…":"Cihazda saxlanıb · yoxlama tələb olunur",12,false));check.setEnabled(false);}else{CompactTaskPomodoro pomodoro=new CompactTaskPomodoro(task);content.addView(pomodoro.panel);taskListPomodoroViews.add(pomodoro);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=0;row.setLayoutParams(lp);homeGroups.add(task,row,"default".equals(taskSortKey));row.setOnClickListener(v->openTaskForm(task,false));row.setOnLongClickListener(v->{showTaskContextMenu(v,task,false);return true;});}homeGroups.finish();if(candidates.length()==0){TextView empty=text(homeQuery.isEmpty()?"Hələlik tapşırıq yoxdur. basın +, əlavə etmək.":"Heç nə tapılmadı",15,false);empty.setTextColor(muted());empty.setGravity(Gravity.CENTER);empty.setPadding(dp(12),dp(28),dp(12),dp(28));homeList.addView(empty);}}
