    private Button toolbarGlyphButton(String description,String glyph){Button b=iconButton("");b.setContentDescription(description);b.setGravity(Gravity.CENTER);b.setCompoundDrawablesWithIntrinsicBounds(new ToolbarGlyph(glyph),null,null,null);return b;}
    private final class ToolbarGlyph extends android.graphics.drawable.Drawable{
        private final String glyph;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
        ToolbarGlyph(String glyph){this.glyph=glyph;paint.setColor(fg());paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(.7f));paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);}
        @Override public void draw(Canvas canvas){android.graphics.Rect bounds=getBounds();if(bounds.width()==0||bounds.height()==0)return;int save=canvas.save();canvas.translate(bounds.left,bounds.top);canvas.scale(bounds.width()/24f,bounds.height()/24f);if(glyph.equals("filter")){android.graphics.Path path=new android.graphics.Path();path.moveTo(4,5);path.lineTo(20,5);path.lineTo(14,12);path.lineTo(14,18);path.lineTo(10,20);path.lineTo(10,12);path.close();canvas.drawPath(path,paint);}else{canvas.drawRoundRect(new RectF(3.5f,4.5f,20.5f,17.5f),3,3,paint);android.graphics.Path tail=new android.graphics.Path();tail.moveTo(8,17.5f);tail.lineTo(7,21);tail.lineTo(12,17.5f);canvas.drawPath(tail,paint);}canvas.restoreToCount(save);}
        @Override public int getIntrinsicWidth(){return dp(22);}@Override public int getIntrinsicHeight(){return dp(22);}
        @Override public void setAlpha(int alpha){paint.setAlpha(alpha);invalidateSelf();}@Override public void setColorFilter(android.graphics.ColorFilter filter){paint.setColorFilter(filter);invalidateSelf();}@Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}
    }
    private android.graphics.drawable.GradientDrawable round(int color,int radius,int stroke,int sw){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(sw>0)d.setStroke(sw,stroke);return d;}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}

