        void zoom(float factor,float cx,float cy){if(!Float.isFinite(factor)||factor<=0)return;float old=scale;scale=Math.max(.05f,Math.min(5f,scale*factor));tx=cx-(cx-tx)*(scale/old);ty=cy-(cy-ty)*(scale/old);saveCamera();invalidate();}
