    private void moveTaskToStatus(JSONObject task,String status,boolean personal){boolean finishing="Done".equalsIgnoreCase(status)||"Is goruldu".equalsIgnoreCase(status);if(finishing&&!TaskHistory.done(task)&&!PendingTasks.pending(task)){CompletionUndo.schedule(this,task.optString("id"),()->commitTaskStatus(task,status,personal));return;}commitTaskStatus(task,status,personal);}
    private void commitTaskStatus(JSONObject task,String status,boolean personal){if(PendingTasks.pending(task)){PendingTasks.show(this,task);return;}
        String old=taskStatus(task);boolean done="Done".equalsIgnoreCase(status)||"Is goruldu".equalsIgnoreCase(status);if(old.equals(status)&&TaskHistory.done(task)==done)return;final JSONObject prior;try{prior=new JSONObject(task.toString());task.put("status",status);task.put("process",status);TaskHistory.mark(task,done);}catch(Exception e){return;}
        render();JSONObject payload=personal?new JSONObject():taskPatch(task,false);try{payload.put("id",task.optString("id")).put(personal?"status":"process",status).put("completed",done);}catch(Exception ignored){}
        IO.execute(()->{JSONObject result=request("PATCH",personal?"/api/personal-task":"/api/task",payload);runOnUiThread(()->{if(result==null){try{task.remove("completedAt");for(Iterator<String> it=prior.keys();it.hasNext();){String k=it.next();task.put(k,prior.get(k));}}catch(Exception ignored){}render();toast("statusu saxlamaq alınmadı");}else{if(done)TaskReminderReceiver.cancel(this,task.optString("id"));if(personal)acceptConfirmedPersonalTask(payload,result,false);else{TaskHistory.confirmed(task,result);render();}}});});
    }

