    private JSONObject taskPatch(JSONObject task,boolean personal){JSONObject p=new JSONObject();try{p.put("id",task.optString("id"));p.put("title",task.optString("title"));p.put("sourceKey",task.optString("sourceKey","todo"));if(personal){p.put("priority",task.optString("priority"));p.put("prioritet",task.optString("prioritet"));p.put("category",task.optString("category"));p.put("date",task.optString("date"));p.put("completed",task.optBoolean("completed"));}else{String machineId=!currentMachineId.isEmpty()?currentMachineId:safeString(task,"machineId");if(machineId.isEmpty())machineId=findMachineForTask(task);p.put("machineId",machineId);String planId=safeString(task,"planId");if(planId.isEmpty()&&currentMachineId.isEmpty()&&activeBoard!=null&&currentPlanId.equals(activeBoard.optString("id")))planId=currentPlanId;if(!planId.isEmpty())p.put("planId",planId);p.put("priority",task.optString("priority"));p.put("date",task.optString("date"));p.put("assigneeId",task.optString("assigneeId"));p.put("tapsirildi",task.optJSONArray("tapsirildi")==null?new JSONArray():task.optJSONArray("tapsirildi"));p.put("gtd",task.optString("gtd"));p.put("workType",task.optString("workType"));p.put("isciTag",task.optString("isciTag"));p.put("tag",task.optString("tag"));p.put("doneWork",task.optString("doneWork"));p.put("completed",task.optBoolean("completed"));}}catch(Exception ignored){}return p;}
