    private JSONArray allEquipmentTasks(){JSONArray out=new JSONArray();java.util.HashSet<String> seen=new java.util.HashSet<>();for(int i=0;i<equipment.length();i++){JSONObject e=equipment.optJSONObject(i);JSONArray ts=e==null?null:e.optJSONArray("tasks");if(ts!=null)for(int j=0;j<ts.length();j++){JSONObject t=ts.optJSONObject(j);if(t!=null&&seen.add(t.optString("id")))out.put(t);}}for(int i=0;i<plans.length();i++){JSONObject p=plans.optJSONObject(i);JSONArray ts=p==null?null:p.optJSONArray("tasks");if(ts!=null)for(int j=0;j<ts.length();j++){JSONObject t=ts.optJSONObject(j);if(t!=null&&seen.add(t.optString("id")))out.put(t);}}return out;}
