    private boolean matches(JSONObject task){if(!TaskHistory.visible(task)||!TaskFilterDialog.matches(task,displayFilters()))return false;if(!search.isEmpty()&&!searchableText(task).contains(normalizeSearch(search)))return false;if(displayFilters().optString("urgent").equals("urgent")){String p=task.optString("priority","")+" "+task.optString("prioritet","");String due=task.optString("date","");if(due.length()>10)due=due.substring(0,10);String today=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new java.util.Date());if(!p.contains("!")&&!p.toUpperCase(java.util.Locale.ROOT).contains("P1")&&(due.isEmpty()||due.compareTo(today)>=0))return false;}return true;}
