    private int eisenhowerQuadrant(JSONObject task){String prioritet=task.optString("prioritet","").trim();if(prioritet.equals("!!!"))return 0;if(prioritet.equals("!!"))return 1;if(prioritet.equals("!"))return 2;if(prioritet.equals("."))return 3;String priority=task.optString("priority","").trim().toUpperCase();String due=task.optString("date","");if(due.length()>10)due=due.substring(0,10);String today=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(new java.util.Date());boolean urgent=priority.equals("!!!")||(!due.isEmpty()&&due.compareTo(today)<=0);String category=task.optString("category","").toLowerCase();boolean important=urgent||priority.equals("!!")||priority.equals("P1")||priority.equals("P2")||category.contains("project")||category.contains("gorulen")||category.contains("sifaris");return urgent?(important?0:2):(important?1:3);}
