    private void movePersonalTaskToQuadrant(JSONObject task,int quadrant){if(PendingTasks.pending(task)){PendingTasks.show(this,task);return;}String[] values={"!!!","!!","!","."};String next=values[quadrant],old=task.optString("prioritet","");if(next.equals(old))return;try{task.put("prioritet",next);}catch(Exception ignored){}renderMatrix();JSONObject payload=new JSONObject();try{payload.put("id",task.optString("id"));payload.put("prioritet",next);}catch(Exception ignored){}IO.execute(()->{JSONObject result=request("PATCH","/api/personal-task",payload);runOnUiThread(()->{if(result==null){try{task.put("prioritet",old);}catch(Exception ignored){}renderMatrix();toast("Matrisdə hərəkəti saxlamaq alınmadı");}});});}
    private EquipmentViewPreferences equipmentViews(){String name="equipment-view:"+DirectRuntime.scopeHash(EquipmentViewPreferences.stableScope(this));android.content.SharedPreferences prefs=getSharedPreferences(name,0);String oldName="equipment-view:"+DirectRuntime.scopeHash(DirectConfig.scope(this));if(!name.equals(oldName)&&!prefs.contains("default")&&!prefs.contains("last")){android.content.SharedPreferences old=getSharedPreferences(oldName,0);android.content.SharedPreferences.Editor migration=prefs.edit();if(old.contains("default"))migration.putString("default",old.getString("default","canvas"));if(old.contains("last"))migration.putString("last",old.getString("last","canvas"));migration.commit();}return new EquipmentViewPreferences(prefs);}
    private void prepareEquipmentView(String view,boolean remember){
        if(!EquipmentViewPreferences.valid(view))view="canvas";
        if(remember)equipmentViews().remember(view);
        if(view.equals("canvas")){screen="canvas";activeBoard=null;listScopeTasks=null;return;}
        JSONArray tasks=resolveTaskListScope();listReturnScreen="canvas";
        if(view.equals("list")){screen="list";listScopeTasks=tasks;return;}
        JSONObject board=new JSONObject();String id=!currentMachineId.isEmpty()?currentMachineId:!currentPlanId.isEmpty()?currentPlanId:"equipment-root";
        String name=!currentMachineId.isEmpty()?findName(equipment,currentMachineId):!currentPlanId.isEmpty()?findName(plans,currentPlanId):"Avadanlıq";
        try{board.put("id",id).put("name",name).put("tasks",tasks);}catch(Exception ignored){}activeBoard=board;listScopeTasks=null;screen="kanban";
    }
    private void setEquipmentView(String view){if(!mode.equals("equipment")||!AccountSession.section("equipment"))return;prepareEquipmentView(view,true);render();}
    private void openEquipment(){if(!AccountSession.section("equipment")){toast("Bölməyə daxil olmaq mümkün deyil");return;}push();mode="equipment";screen="canvas";currentPlanId="";currentMachineId="";personalContainerId="";activeBoard=null;listScopeTasks=null;search="";taskListReturnState=null;taskListReturnHistory.clear();
        JSONObject start=findPlanByName("ADIB");if(start==null)for(int i=0;i<plans.length();i++){JSONObject p=plans.optJSONObject(i);if(p!=null&&!hasValue(p,"parentId")){start=p;break;}}if(start!=null)currentPlanId=start.optString("id");
        prepareEquipmentView(equipmentViews().resolveDefault(),false);render();refreshSection(false,true,false);
    }
