    private void showTaskList(){listReturnScreen=screen;if(screen.equals("canvas"))activeBoard=null;listScopeTasks=resolveTaskListScope();screen="list";render();}
    private JSONArray resolveTaskListScope(){
        if(screen.equals("kanban")&&activeBoard!=null)return tasksForBoard();
        if(mode.equals("personal")){if(!personalContainerId.isEmpty()){JSONArray scoped=new JSONArray();for(int i=0;i<personalTasks.length();i++){JSONObject t=personalTasks.optJSONObject(i);if(visiblePersonalRoot(t)&&personalContainerId.equals(t.optString("containerId","")))scoped.put(t);}return scoped;}return personalRootTasks(personalTasks);}
        JSONArray all=allEquipmentTasks(),result=new JSONArray();java.util.HashSet<String> ids=new java.util.HashSet<>();
        if(!currentMachineId.isEmpty()){
            JSONObject machine=find(equipment,currentMachineId);JSONArray own=machine==null?null:machine.optJSONArray("tasks");appendUniqueTasks(result,ids,own);
            for(int i=0;i<all.length();i++){JSONObject t=all.optJSONObject(i);if(t!=null&&(currentMachineId.equals(safeString(t,"machineId"))||currentMachineId.equals(findMachineForTask(t))))appendUniqueTask(result,ids,t);}return result;
        }
        if(!currentPlanId.isEmpty())return tasksForPlanTree(currentPlanId);
        return all;
    }
    // Include the selected plan and descendants of any depth; the visited set prevents cycles.
    private java.util.HashSet<String> descendantPlanIds(String rootId){
        java.util.HashSet<String> ids=new java.util.HashSet<>();
        if(rootId==null||rootId.isEmpty())return ids;
        ids.add(rootId);boolean changed=true;
        while(changed){changed=false;for(int i=0;i<plans.length();i++){
            JSONObject plan=plans.optJSONObject(i);if(plan==null)continue;
            String id=plan.optString("id","");
            if(!id.isEmpty()&&ids.contains(plan.optString("parentId",""))&&ids.add(id))changed=true;
        }}return ids;
    }
    private JSONArray tasksForPlanTree(String rootId){
        java.util.HashSet<String> planIds=descendantPlanIds(rootId),taskIds=new java.util.HashSet<>(),machineIds=new java.util.HashSet<>();
        JSONArray result=new JSONArray();
        for(int i=0;i<plans.length();i++){
            JSONObject plan=plans.optJSONObject(i);if(plan==null||!planIds.contains(plan.optString("id","")))continue;
            appendOwnedTasks(result,taskIds,plan.optJSONArray("tasks"),"planId",plan.optString("id",""));
        }
        for(int i=0;i<equipment.length();i++){
            JSONObject machine=equipment.optJSONObject(i);if(machine==null||!planIds.contains(machine.optString("planId","")))continue;
            machineIds.add(machine.optString("id",""));
            appendOwnedTasks(result,taskIds,machine.optJSONArray("tasks"),"machineId",machine.optString("id",""));
        }
        JSONArray all=allEquipmentTasks();for(int i=0;i<all.length();i++){
            JSONObject task=all.optJSONObject(i);if(task!=null&&(planIds.contains(safeString(task,"planId"))||machineIds.contains(safeString(task,"machineId"))))appendUniqueTask(result,taskIds,task);
        }return result;
    }
    private void appendOwnedTasks(JSONArray target,java.util.HashSet<String> ids,JSONArray tasks,String ownerKey,String ownerId){
        if(tasks==null)return;for(int i=0;i<tasks.length();i++){
            JSONObject task=tasks.optJSONObject(i);if(task==null)continue;
            // Keep the real owner for edits from an aggregated parent-plan list.
            if(safeString(task,ownerKey).isEmpty())try{task.put(ownerKey,ownerId);}catch(Exception ignored){}
            appendUniqueTask(target,ids,task);
        }
    }
    private void appendUniqueTasks(JSONArray target,java.util.HashSet<String> ids,JSONArray source){if(source==null)return;for(int i=0;i<source.length();i++)appendUniqueTask(target,ids,source.optJSONObject(i));}
    private void appendUniqueTask(JSONArray target,java.util.HashSet<String> ids,JSONObject task){if(task==null)return;String id=task.optString("id","");if(id.isEmpty()||ids.add(id))target.put(task);}
    private ArrayList<JSONObject> childPersonalContainers(String parentId){
        ArrayList<JSONObject> children=new ArrayList<>();for(int i=0;i<personalContainers.length();i++){
            JSONObject container=personalContainers.optJSONObject(i);if(container==null)continue;
            String parent=hasValue(container,"parentId")?container.optString("parentId"):"";
            if(parentId.equals(parent)&&!parentId.equals(container.optString("id","")))children.add(container);
        }children.sort((a,b)->{int order=Integer.compare(a.optInt("order",0),b.optInt("order",0));return order!=0?order:a.optString("name","").compareToIgnoreCase(b.optString("name",""));});return children;
    }
