    private void takePhoto(java.util.function.Consumer<java.util.List<JSONObject>> consumer){
        if(imagePickConsumer!=null){toast("Şəkil seçiminin tamamlanmasını gözləyin");return;}
        imagePickConsumer=consumer;
        try{pendingCameraUri=CameraPhotoProvider.create(this);startActivityForResult(CameraPhotoProvider.intent(this,pendingCameraUri),CameraPhotoProvider.CAPTURE_IMAGE);}
        catch(Exception e){CameraPhotoProvider.discard(this,pendingCameraUri);pendingCameraUri=null;imagePickConsumer=null;toast("Kameranı açmaq alınmadı. Siz qalereyadan bir şəkil seçə bilərsiniz.");}
    }
    private void receiveCameraImage(int resultCode){
        android.net.Uri uri=pendingCameraUri;pendingCameraUri=null;
        java.util.function.Consumer<java.util.List<JSONObject>> consumer=imagePickConsumer;imagePickConsumer=null;
        if(resultCode!=RESULT_OK){CameraPhotoProvider.discard(this,uri);return;}
        if(uri==null||consumer==null){CameraPhotoProvider.discard(this,uri);toast("Tapşırıq ekranı sistem tərəfindən bağlanıb. Tapşırığı açın və yenidən şəkil çəkin.");return;}
        toast("Şəkil hazırlanır…");final int target=imagePickTarget;
        NativeImageSupport.IO.execute(()->{try{
            if(CameraPhotoProvider.file(this,uri).length()==0)throw new java.io.IOException("Kamera şəkli saxlamadı");
            JSONObject image=NativeImageSupport.readPhoto(this,uri,target);
            runOnUiThread(()->{if(!isDestroyed()){consumer.accept(java.util.Collections.singletonList(image));if(chatScreenOpen&&chatConversationOpen)showChatPage();}});
        }catch(Exception e){runOnUiThread(()->toast("Snapşotu oxumaq alınmadı: "+e.getMessage()));}
        finally{CameraPhotoProvider.discard(this,uri);}});
    }
