    private long parseReminderTime(String value){
        try{
            if(value.length()>=16&&value.charAt(10)=='T'){java.util.Date d=TaskCalendarModel.parseDateTime(value);if(d!=null)return d.getTime();}
            if(value.length()>=10){java.util.Calendar c=java.util.Calendar.getInstance();c.set(Integer.parseInt(value.substring(0,4)),Integer.parseInt(value.substring(5,7))-1,Integer.parseInt(value.substring(8,10)),9,0,0);c.set(java.util.Calendar.MILLISECOND,0);long at=c.getTimeInMillis();if(at<=System.currentTimeMillis()&&c.get(java.util.Calendar.YEAR)==java.util.Calendar.getInstance().get(java.util.Calendar.YEAR)&&c.get(java.util.Calendar.DAY_OF_YEAR)==java.util.Calendar.getInstance().get(java.util.Calendar.DAY_OF_YEAR))return System.currentTimeMillis()+30_000L;return at;}
        }catch(Exception ignored){}
        return 0;
    }
