    private void refreshChatThreads(){if(chatScreenOpen)refreshEmployeeChats();if(chatRequestRunning)return;chatRequestRunning=true;lastChatRefreshAt=android.os.SystemClock.elapsedRealtime();JSONObject payload=new JSONObject();try{JSONArray candidates=chatCandidates();if(candidates.length()==0){chatRequestRunning=false;return;}payload.put("tasks",candidates);getPreferences(0).edit().putString("chat_candidates_cache",candidates.toString()).apply();}catch(Exception ignored){}IO.execute(()->{JSONObject result=request("POST","/api/chat-threads",payload);runOnUiThread(()->{chatRequestRunning=false;if(result==null){if(chatState!=null){chatState.setVisibility(View.VISIBLE);chatState.setText("Söhbəti yeniləmək alınmadı. Saxlanmış mesajlar göstərilir.");}return;}if(result.optJSONArray("threads")==null)return;chatThreads=EmployeeChats.merge(this,result.optJSONArray("threads"));processIncomingChatComments();if(chatScreenOpen){renderChatThreads();if(chatConversationOpen)renderChatMessages();if(chatState!=null)chatState.setVisibility(View.GONE);}});});}
    private TextView chatUnreadBadge;private boolean chatAlertReceiverRegistered=false;
    private final android.content.BroadcastReceiver chatAlertReceiver=new android.content.BroadcastReceiver(){@Override public void onReceive(android.content.Context context,Intent intent){if(!ChatNotifications.ACTION_NEW.equals(intent.getAction()))return;try{chatThreads=new JSONArray(getPreferences(0).getString("chat_threads_cache","[]"));}catch(Exception ignored){}updateChatUnreadBadge();if(chatScreenOpen){renderChatThreads();if(chatConversationOpen)renderChatMessages();}showCommentBanner(intent.getStringExtra("title"),intent.getStringExtra("body"),intent.getStringExtra(ChatNotifications.EXTRA_TASK));}};
    private void updateChatUnreadBadge(){if(chatThreads.length()==0)try{chatThreads=new JSONArray(getPreferences(0).getString("chat_threads_cache","[]"));}catch(Exception ignored){}int count=ChatNotifications.unread(this,EmployeeChats.tasks(chatThreads));for(int i=0;i<chatThreads.length();i++){JSONObject t=chatThreads.optJSONObject(i);if(t!=null&&t.optBoolean("isEmployee"))count+=t.optInt("unreadCount");}if(chatUnreadBadge!=null){chatUnreadBadge.setText(count>99?"99+":String.valueOf(count));chatUnreadBadge.setVisibility(count>0?View.VISIBLE:View.GONE);}}
    private void showCommentBanner(String title,String body,String task){FrameLayout decor=(FrameLayout)getWindow().getDecorView();View old=decor.findViewWithTag("adib-comment-banner");if(old!=null)decor.removeView(old);LinearLayout box=new LinearLayout(this);box.setTag("adib-comment-banner");box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(10),dp(12),dp(8));box.setBackground(round(panel(),12,BLUE,dp(2)));TextView heading=text(title==null?"Yeni şərh":title,14,true),preview=text(body==null?"":body,13,false);preview.setMaxLines(3);box.addView(heading);box.addView(preview);LinearLayout actions=new LinearLayout(this);Button open=button("Müzakirə",BLUE,Color.WHITE),close=button("×",Color.TRANSPARENT,BLUE);actions.addView(open,new LinearLayout.LayoutParams(0,dp(44),1));actions.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));box.addView(actions);FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP);params.setMargins(dp(12),dp(52),dp(12),0);decor.addView(box,params);open.setOnClickListener(v->{decor.removeView(box);openNotifiedChat(task);});close.setOnClickListener(v->decor.removeView(box));box.postDelayed(()->{if(box.getParent()==decor)decor.removeView(box);},12000);}
    private void openTaskDiscussion(JSONObject task){String id=task.optString("id");if(id.isEmpty())return;explicitDiscussionTask=task;boolean found=false;for(int i=0;i<chatThreads.length();i++){JSONObject thread=chatThreads.optJSONObject(i);if(thread!=null&&id.equals(thread.optString("taskId"))){found=true;break;}}if(!found)try{chatThreads.put(new JSONObject().put("taskId",id).put("title",task.optString("title","Tapşırıq")).put("source","Tapşırıq").put("comments",new JSONArray()));}catch(Exception ignored){}getPreferences(0).edit().putString("chat_threads_cache",EmployeeChats.tasks(chatThreads).toString()).apply();lastChatRefreshAt=0;openNotifiedChat(id);}
    private void openNotifiedChat(String task){activeChatTaskId=task==null?"":task;showChat();chatConversationOpen=!activeChatTaskId.isEmpty();showChatPage();if(EmployeeChats.isEmployee(activeChatTaskId))loadEmployeeChat(activeChatTaskId);}
    private void processIncomingChatComments(){ChatNotifications.publish(this,ChatNotifications.accept(this,EmployeeChats.tasks(chatThreads)));updateChatUnreadBadge();chatInitialLoad=false;}
    private void renderChatThreads(){if(chatThreadList==null)return;chatThreadList.removeAllViews();Set<String> seen=getPreferences(0).getStringSet("chat_seen_ids",new HashSet<>());for(int i=0;i<chatThreads.length();i++){JSONObject thread=chatThreads.optJSONObject(i);if(thread==null)continue;String id=thread.optString("taskId");if(!chatKindFilter.equals("all")&&(chatKindFilter.equals("employees")!=EmployeeChats.isEmployee(id)))continue;JSONArray comments=thread.optJSONArray("comments");JSONObject last=comments==null||comments.length()==0?null:comments.optJSONObject(comments.length()-1);String query=chatSearch==null?"":chatSearch.getText().toString().trim().toLowerCase(Locale.ROOT);String searchable=thread.optString("title")+" "+thread.optString("source")+" "+thread.optString("machineName")+" "+(last==null?"":last.optString("text"));if(!query.isEmpty()&&!searchable.toLowerCase(Locale.ROOT).contains(query))continue;boolean unread=false;if(comments!=null)for(int j=0;j<comments.length();j++){JSONObject c=comments.optJSONObject(j);if(c!=null&&!seen.contains(c.optString("id"))&&!ChatNotifications.own(c.optString("authorName",""),(AccountSession.user==null?getPreferences(0).getString("comment_user","ilqar mamedov"):AccountSession.user.optString("name"))))unread=true;}
        LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.setBackground(round(id.equals(activeChatTaskId)?(dark?Color.rgb(52,59,76):Color.rgb(232,240,255)):panel(),12,Color.rgb(225,227,232),dp(1)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(6);chatThreadList.addView(row,rp);
        TextView avatar=text(ChatPresentation.initials(thread.optString("title","")),17,true);avatar.setGravity(Gravity.CENTER);avatar.setTextColor(Color.WHITE);avatar.setBackground(round(BLUE,28,Color.TRANSPARENT,0));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(42),dp(42));ap.rightMargin=dp(10);row.addView(avatar,ap);
        LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView taskName=text(thread.optString("title","Tapşırıq"),15,true);taskName.setMaxLines(2);taskName.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(taskName);TextView meta=text(android.text.TextUtils.join(" · ",nonEmpty(thread.optString("source"),thread.optString("machineName"))),11,false);meta.setTextColor(muted());info.addView(meta);TextView preview=text(last==null?"Hələ şərh yoxdur":last.optString("authorName","İstifadəçi")+": "+(last.optString("text","").isEmpty()&&last.optJSONArray("attachments")!=null&&last.optJSONArray("attachments").length()>0?"📷 Foto":last.optString("text","")),12,false);preview.setSingleLine(true);preview.setEllipsize(android.text.TextUtils.TruncateAt.END);preview.setTextColor(muted());info.addView(preview);
        if(thread.optBoolean("isEmployee"))unread=thread.optInt("unreadCount")>0;if(unread){TextView badge=text("●",13,true);badge.setTextColor(BLUE);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.leftMargin=dp(8);row.addView(badge,bp);}row.setOnClickListener(v->{activeChatTaskId=id;chatConversationOpen=true;markChatRead(id);renderChatThreads();showChatPage();if(EmployeeChats.isEmployee(id))loadEmployeeChat(id);});}}
    private View commentCard(JSONObject comment,boolean chat){
        LinearLayout card=new LinearLayout(this);card.setTag("comment-card:"+comment.optString("id"));card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(10),dp(8),dp(10),dp(8));boolean mine=comment.optString("authorName","").equalsIgnoreCase((AccountSession.user==null?getPreferences(0).getString("comment_user","ilqar mamedov"):AccountSession.user.optString("name")));card.setBackground(round(mine?HybridUi.outgoing(dark):HybridUi.soft(dark),18,Color.TRANSPARENT,0));
        TextView author=text(comment.optString("authorName","İstifadəçi"),11,true);card.addView(author);TextView body=text(comment.optString("text",""),14,false);body.setMaxWidth(dp(260));card.addView(body);NativeImageSupport.showCommentImages(this,card,comment.optJSONArray("attachments"));TextView time=text(CommentTime.format(comment.optString("createdAt")),10,false);time.setTextColor(muted());time.setContentDescription(CommentTime.full(comment.optString("createdAt")));card.addView(time);return card;
    }
    private void renderChatMessages(){if(chatMessageList==null)return;int oldY=chatMessageScroll==null?0:chatMessageScroll.getScrollY();boolean same=activeChatTaskId.equals(chatRenderedTaskId);boolean bottom=chatMessageScroll==null||oldY+chatMessageScroll.getHeight()>=chatMessageList.getHeight()-dp(64);chatMessageList.removeAllViews();JSONObject selected=null;for(int i=0;i<chatThreads.length();i++){JSONObject thread=chatThreads.optJSONObject(i);if(thread!=null&&activeChatTaskId.equals(thread.optString("taskId"))){selected=thread;break;}}if(selected==null){chatConversationOpen=false;showChatPage();return;}if(chatConversationTitle!=null)chatConversationTitle.setText(selected.optString("title","Tapşırıq"));JSONArray comments=selected.optJSONArray("comments");String day="";JSONObject previous=null;if(comments!=null)for(int i=0;i<comments.length();i++){JSONObject comment=comments.optJSONObject(i);if(comment==null)continue;String date=comment.optString("createdAt"),key=ChatPresentation.dayKey(date),author=comment.optString("authorName","İstifadəçi");boolean grouped=previous!=null&&ChatPresentation.grouped(previous.optString("authorName"),previous.optString("createdAt"),author,date);if(!key.equals(day)){TextView separator=text(ChatPresentation.day(date),11,true);separator.setTag("chat-day:"+key);separator.setGravity(Gravity.CENTER);separator.setTextColor(muted());separator.setPadding(0,dp(14),0,dp(14));chatMessageList.addView(separator,new LinearLayout.LayoutParams(-1,-2));day=key;}boolean mine=ChatNotifications.own(author,(AccountSession.user==null?getPreferences(0).getString("comment_user","ilqar mamedov"):AccountSession.user.optString("name")));LinearLayout line=new LinearLayout(this);line.setTag(mine?"chat-row-mine":"chat-row-incoming");line.setGravity((mine?Gravity.RIGHT:Gravity.LEFT)|Gravity.BOTTOM);LinearLayout card=new LinearLayout(this);card.setTag("chat-bubble:"+comment.optString("id"));card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(7));card.setBackground(round(mine?HybridUi.outgoing(dark):panel(),18,Color.TRANSPARENT,0));if(!grouped&&!mine){TextView sender=text(author,11,true);sender.setTag("chat-sender");sender.setTextColor(BLUE);card.addView(sender);}if(!comment.optString("text").isEmpty()){TextView body=text(comment.optString("text"),15,false);body.setTextIsSelectable(true);body.setMaxWidth(Math.max(dp(120),Math.min(dp(300),getResources().getDisplayMetrics().widthPixels-dp(96))));card.addView(body);}NativeImageSupport.showCommentImages(this,card,comment.optJSONArray("attachments"));TextView time=text(ChatPresentation.clock(date),10,false);time.setGravity(Gravity.RIGHT);time.setTextColor(muted());time.setContentDescription(CommentTime.full(date));card.addView(time);line.addView(card,new LinearLayout.LayoutParams(-2,-2));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(grouped?2:8);lp.bottomMargin=dp(2);chatMessageList.addView(line,lp);previous=comment;}if(comments==null||comments.length()==0){TextView empty=text("Problemlə bağlı müzakirəyə başlayın",14,false);empty.setTextColor(muted());empty.setGravity(Gravity.CENTER);empty.setPadding(0,dp(32),0,dp(32));chatMessageList.addView(empty);}chatRenderedTaskId=activeChatTaskId;if(chatMessageScroll!=null){final ScrollView scroll=chatMessageScroll;final boolean follow=!same||bottom;scroll.post(()->{if(scroll==chatMessageScroll){if(follow)scroll.fullScroll(View.FOCUS_DOWN);else scroll.scrollTo(0,oldY);}});}markChatRead(activeChatTaskId);renderChatThreads();}
    private void markChatRead(String taskId){if(EmployeeChats.isEmployee(taskId))return;Set<String> seen=new HashSet<>(getPreferences(0).getStringSet("chat_seen_ids",new HashSet<>()));for(int i=0;i<chatThreads.length();i++){JSONObject thread=chatThreads.optJSONObject(i);if(thread==null||!taskId.equals(thread.optString("taskId")))continue;JSONArray comments=thread.optJSONArray("comments");if(comments!=null)for(int j=0;j<comments.length();j++){JSONObject c=comments.optJSONObject(j);if(c!=null&&!c.optString("id").isEmpty())seen.add(c.optString("id"));}}getPreferences(0).edit().putStringSet("chat_seen_ids",seen).apply();updateChatUnreadBadge();}
    private void sendChatComment(){if(chatComposer==null||activeChatTaskId.isEmpty())return;if(EmployeeChats.isEmployee(activeChatTaskId)){sendEmployeeMessage();return;}final String taskId=activeChatTaskId,textValue=chatComposer.getText().toString().trim();NativeImageSupport.Draft draft=commentImageDrafts.computeIfAbsent(taskId,k->new NativeImageSupport.Draft());if(draft.busy||textValue.isEmpty()&&!draft.has())return;saveChatDraft();draft.busy=true;chatComposer.setEnabled(false);NativeImageSupport.IO.execute(()->{try{JSONObject payload=new JSONObject().put("id",taskId).put("text",textValue).put("authorName",(AccountSession.user==null?getPreferences(0).getString("comment_user","ilqar mamedov"):AccountSession.user.optString("name"))).put("attachments",draft.upload());JSONObject result=NativeImageSupport.transport.call("POST","/api/task-comments",payload);runOnUiThread(()->{draft.busy=false;draft.images.clear();chatTextDrafts.remove(taskId);if(chatComposer!=null&&taskId.equals(activeChatTaskId)){chatComposer.setEnabled(true);chatComposer.setText("");}JSONObject saved=result.optJSONObject("comment");if(saved!=null){for(int i=0;i<chatThreads.length();i++){JSONObject th=chatThreads.optJSONObject(i);if(th!=null&&taskId.equals(th.optString("taskId"))){JSONArray comments=th.optJSONArray("comments");if(comments==null){comments=new JSONArray();try{th.put("comments",comments);}catch(Exception ignored){}}comments.put(saved);getPreferences(0).edit().putString("chat_threads_cache",EmployeeChats.tasks(chatThreads).toString()).apply();break;}}}if(chatScreenOpen)showChatPage();refreshChatThreads();toast("Şərh yadda saxlanıldı");});}catch(Exception e){runOnUiThread(()->{draft.busy=false;if(chatComposer!=null)chatComposer.setEnabled(!commentImageDrafts.computeIfAbsent(activeChatTaskId,k->new NativeImageSupport.Draft()).busy);toast("Göndərmək alınmadı: "+e.getMessage());});}});}
    private void refreshEmployeeChats(){if(!chatScreenOpen||DirectRuntime.enabled())return;EmployeeChats.refresh(this,(r,e)->{if(!chatScreenOpen)return;if(r==null){if(chatState!=null){chatState.setVisibility(View.VISIBLE);chatState.setText(e);}return;}chatThreads=EmployeeChats.merge(this,chatThreads);renderChatThreads();updateChatUnreadBadge();if(EmployeeChats.isEmployee(activeChatTaskId)&&chatConversationOpen){JSONObject t=null;for(int i=0;i<chatThreads.length();i++){JSONObject v=chatThreads.optJSONObject(i);if(v!=null&&activeChatTaskId.equals(v.optString("taskId")))t=v;}if(t!=null&&!t.optBoolean("loaded"))loadEmployeeChat(activeChatTaskId);}});}
    private void loadEmployeeChat(String id){EmployeeChats.load(this,id,(r,e)->{if(!chatScreenOpen)return;if(r==null){if(chatState!=null){chatState.setVisibility(View.VISIBLE);chatState.setText(e);}return;}chatThreads=EmployeeChats.merge(this,chatThreads);if(id.equals(activeChatTaskId))showChatPage();renderChatThreads();updateChatUnreadBadge();});}
    private void chooseEmployeeChat(){EmployeeChats.refresh(this,(r,e)->{if(!chatScreenOpen)return;if(r==null||!r.optBoolean("available")){toast(r==null?e:"Əməkdaşlarla söhbət üçün ADIB hesabına daxil olun");return;}JSONArray peers=EmployeeChats.peers(this);if(peers.length()==0){toast("Aktiv ADIB əməkdaşı yoxdur");return;}String[] names=new String[peers.length()];for(int i=0;i<peers.length();i++)names[i]=peers.optJSONObject(i).optString("name");dialogBuilder().setTitle("Əməkdaşla söhbət").setItems(names,(d,index)->{JSONObject peer=peers.optJSONObject(index);String id="employee:"+peer.optString("id");try{EmployeeChats.chats.put(peer.optString("id"),EmployeeChats.thread(peer.optString("id"),peer.optString("name"),new JSONArray()));chatThreads=EmployeeChats.merge(this,chatThreads);}catch(Exception ignored){}activeChatTaskId=id;chatConversationOpen=true;showChatPage();loadEmployeeChat(id);}).setNegativeButton("Bağla",null).show();});}
    private void sendEmployeeMessage(){String id=activeChatTaskId,text=chatComposer.getText().toString().trim();if(text.isEmpty()||!chatComposer.isEnabled())return;saveChatDraft();chatComposer.setEnabled(false);EmployeeChats.send(this,id,text,(r,e)->{if(r==null){toast("Göndərmək alınmadı: "+e);if(chatComposer!=null&&id.equals(activeChatTaskId))chatComposer.setEnabled(true);return;}chatTextDrafts.remove(id);chatThreads=EmployeeChats.merge(this,chatThreads);if(chatComposer!=null&&id.equals(activeChatTaskId)){chatComposer.setText("");chatComposer.setEnabled(true);showChatPage();}renderChatThreads();updateChatUnreadBadge();});}
    private void renderTaskComments(TextView target,JSONArray comments){if(!(target.getParent() instanceof LinearLayout))return;LinearLayout parent=(LinearLayout)target.getParent();View old=parent.findViewWithTag("task-comments-inline");if(old!=null)parent.removeView(old);if(comments==null||comments.length()==0){target.setText("Hələ şərh yoxdur");target.setVisibility(View.VISIBLE);return;}target.setVisibility(View.GONE);LinearLayout list=new LinearLayout(this);list.setTag("task-comments-inline");list.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<comments.length();i++){JSONObject c=comments.optJSONObject(i);if(c==null)continue;LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);View card=commentCard(c,false);if(parent.getParent()!=null&&parent.getParent() instanceof ScrollView&&((ScrollView)parent.getParent()).getTag()!=null&&"task-pane:0".equals(((ScrollView)parent.getParent()).getTag())){LinearLayout row=new LinearLayout(this);row.setGravity(ChatNotifications.own(c.optString("authorName"),(AccountSession.user==null?getPreferences(0).getString("comment_user","ilqar mamedov"):AccountSession.user.optString("name")))?Gravity.RIGHT:Gravity.LEFT);row.addView(card,new LinearLayout.LayoutParams(-2,-2));list.addView(row,lp);}else list.addView(card,lp);}parent.addView(list,parent.indexOfChild(target)+1);}
    private void loadTaskComments(String id,TextView target){if(target==null)return;NativeImageSupport.IO.execute(()->{try{JSONObject result=NativeImageSupport.transport.call("GET","/api/task-comments?id="+android.net.Uri.encode(id),null);runOnUiThread(()->{if(result==null){target.setVisibility(View.VISIBLE);target.setText("Şərhləri yeniləmək alınmadı");return;}renderTaskComments(target,result.optJSONArray("comments"));});}catch(Exception e){runOnUiThread(()->{target.setVisibility(View.VISIBLE);target.setText("Şərhləri yeniləmək alınmadı");});}});}
    private void deleteTask(JSONObject task,boolean personal){try{OfflineDeletes.enqueue(this,task,personal,currentMachineId);String id=task.optString("id");confirmedCreations.remove(id);confirmedCreationTimes.remove(id);taskMutationGeneration++;maskLocalDeletes();render();toast("Cihazda silindi · sinxronizasiya gözlənilir");}catch(Exception e){toast("Silinmə yadda saxlanılmadı: "+e.getMessage());}}
    private void createPlan(){EditText name=new EditText(uiContext());name.setContentDescription("Planın adı");dialogBuilder().setTitle("Yeni plan").setView(name).setNegativeButton("Ləğv et",null).setPositiveButton("Yaradın",(d,w)->{JSONObject p=new JSONObject();try{p.put("name",name.getText().toString());p.put("parentId",currentPlanId);}catch(Exception ignored){}send("POST","/api/plan",p,r->{refresh(true);toast("Plan yaradıldı");});}).show();}
    private void createEquipment(){EditText name=new EditText(uiContext());name.setContentDescription("Avadanlığın adı");ArrayList<String> labels=new ArrayList<>();ArrayList<String> ids=new ArrayList<>();for(int i=0;i<plans.length();i++){JSONObject p=plans.optJSONObject(i);if(p!=null){labels.add(p.optString("name"));ids.add(p.optString("id"));}}if(labels.isEmpty()){toast("Əvvəlcə plan yaradın");return;}Spinner choose=new Spinner(uiContext());choose.setAdapter(adapter(labels.toArray(new String[0])));LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),0,dp(20),0);f.addView(name);f.addView(label("Plan"));f.addView(choose);dialogBuilder().setTitle("Yeni avadanlıq").setView(f).setNegativeButton("Ləğv et",null).setPositiveButton("Yaradın",(d,w)->{JSONObject p=new JSONObject();try{p.put("name",name.getText().toString());p.put("planId",ids.get(choose.getSelectedItemPosition()));}catch(Exception ignored){}send("POST","/api/equipment",p,r->{refresh(true);toast("Avadanlıq yaradıldı");});}).show();}
    private void createContainer(){EditText name=new EditText(uiContext());name.setContentDescription("Konteyner adı");dialogBuilder().setTitle("Yeni konteyner").setView(name).setNegativeButton("Ləğv et",null).setPositiveButton("Yaradın",(d,w)->{JSONObject p=new JSONObject();try{p.put("name",name.getText().toString());p.put("parentId",personalContainerId);}catch(Exception ignored){}send("POST","/api/personal-container",p,r->{refresh(true);toast("Konteyner yaradıldı");});}).show();}
    private void createPlanUnder(String parentId){EditText name=new EditText(uiContext());name.setContentDescription("Planın adı");dialogBuilder().setTitle("Yeni daxili plan").setView(name).setNegativeButton("Ləğv et",null).setPositiveButton("Yaradın",(d,w)->{JSONObject p=new JSONObject();try{p.put("name",name.getText().toString());p.put("parentId",parentId);}catch(Exception ignored){}send("POST","/api/plan",p,r->{refresh(true);toast("Plan yaradıldı");});}).show();}
    private void createContainerUnder(String parentId){EditText name=new EditText(uiContext());name.setContentDescription("Konteyner adı");dialogBuilder().setTitle("Yeni daxili konteyner").setView(name).setNegativeButton("Ləğv et",null).setPositiveButton("Yaradın",(d,w)->{JSONObject p=new JSONObject();try{p.put("name",name.getText().toString());p.put("parentId",parentId);}catch(Exception ignored){}send("POST","/api/personal-container",p,r->{refresh(true);toast("Konteyner yaradıldı");});}).show();}
    private JSONObject findPlanByName(String name){for(int i=0;i<plans.length();i++){JSONObject p=plans.optJSONObject(i);if(p!=null&&name.equalsIgnoreCase(p.optString("name","")))return p;}return null;}
    private void loadUsers(){if(usersLoading)return;usersLoading=true;IO.execute(()->{JSONObject result=request("GET","/api/users",null);runOnUiThread(()->{usersLoading=false;if(result!=null&&result.optJSONArray("users")!=null)notionUsers=result.optJSONArray("users");});});}
    private String safeString(JSONObject object,String key){return object==null||object.isNull(key)?"":object.optString(key,"");}
    private String findMachineForTask(JSONObject task){String id=task==null?"":task.optString("id");for(int i=0;i<equipment.length();i++){JSONObject e=equipment.optJSONObject(i);JSONArray ts=e==null?null:e.optJSONArray("tasks");if(ts==null)continue;for(int j=0;j<ts.length();j++){JSONObject t=ts.optJSONObject(j);if(t!=null&&id.equals(t.optString("id")))return e.optString("id");}}return "";}
    private JSONObject find(JSONArray a,String id){for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&id.equals(o.optString("id")))return o;}return null;}
    private String findName(JSONArray a,String id){JSONObject o=find(a,id);return o==null?"":o.optString("name","");}
    private void applyWidgetNavigation(Intent intent){if(intent==null)return;if(intent.hasExtra("compact_nav")){String tab=intent.getStringExtra("compact_nav");intent.removeExtra("compact_nav");if("chat".equals(tab)&&AccountSession.section("chat")){new HandlerOnce().run(this::showChat);return;}if("matrix".equals(tab)&&AccountSession.section("matrix")){mode="matrix";screen="list";return;}if("timer".equals(tab)){new HandlerOnce().run(this::showTimerHub);return;}if("home".equals(tab)){mode="personal";screen="home";return;}}String action=intent.getAction();if(ACTION_QUICK_ADD.equals(action)){mode="personal";screen="canvas";activeBoard=null;return;}if(ACTION_WIDGET_MY_TASKS.equals(action)){mode="personal";screen="list";personalContainerId="";activeBoard=null;listScopeTasks=null;listReturnScreen="canvas";return;}if(ACTION_WIDGET_KANBAN.equals(action)){mode="personal";openPersonalKanban();return;}if(ACTION_WIDGET_URGENT.equals(action)){mode="personal";filter="urgent";rememberDisplayFilters();openPersonalKanban();return;}if(ACTION_WIDGET_EQUIPMENT.equals(action)){mode="equipment";screen="canvas";currentPlanId="";currentMachineId="";personalContainerId="";activeBoard=null;return;}if(ACTION_WIDGET_CONTAINER_KANBAN.equals(action)){mode="personal";screen="kanban";pendingWidgetContainerId=intent.getStringExtra("widget_id");JSONObject box=find(personalContainers,pendingWidgetContainerId);if(box!=null){pendingWidgetContainerId="";openPersonalContainerKanban(box);}return;}if(ACTION_WIDGET_TASK.equals(action)){String suppliedScope=intent.getStringExtra("calendar_task_scope");if(suppliedScope!=null&&!suppliedScope.equals(DirectConfig.scope(this))){toast("Hesab dəyişdi. Təqvimi yenidən açın.");return;}pendingWidgetTaskSource=intent.getStringExtra("calendar_task_source")==null?"":intent.getStringExtra("calendar_task_source");mode=CalendarTaskNavigation.equipment(pendingWidgetTaskSource)?"equipment":"personal";screen="canvas";finishAfterCalendarTask=intent.getBooleanExtra("calendar_return_to_calendar",false);pendingWidgetTaskId=intent.getStringExtra("widget_id")==null?"":intent.getStringExtra("widget_id");return;}if(ACTION_WIDGET_EQUIPMENT_ITEM.equals(action)){push();mode="equipment";screen="canvas";activeBoard=null;String id=intent.getStringExtra("widget_id");if("machine".equals(intent.getStringExtra("widget_kind"))){currentMachineId=id;currentPlanId="";}else{currentPlanId=id;currentMachineId="";}}}
    private void processPendingWidgetNavigation(){if(!pendingWidgetContainerId.isEmpty()){JSONObject box=find(personalContainers,pendingWidgetContainerId);if(box!=null){pendingWidgetContainerId="";openPersonalContainerKanban(box);return;}}if(!pendingWidgetTaskId.isEmpty()){JSONObject task=CalendarTaskNavigation.find(pendingWidgetTaskId,pendingWidgetTaskSource,personalTasks,personalPomodoroTasks,equipmentPomodoroTasks,plans,equipment,WorkTimerClient.snapshot(this).optJSONArray("tasks"));if(task!=null){boolean equipmentTask=CalendarTaskNavigation.equipment(task.optString("sourceKey"))||CalendarTaskNavigation.equipment(pendingWidgetTaskSource);if(!AccountSession.section(equipmentTask?"equipment":"personal")){toast("Tapşırığa giriş yoxdur");pendingWidgetTaskId="";if(finishAfterCalendarTask)finish();return;}mode=equipmentTask?"equipment":"personal";if(equipmentTask){source=task.optString("sourceKey",pendingWidgetTaskSource);currentMachineId=task.optString("machineId",findMachineForTask(task));currentPlanId=task.optString("planId","");}pendingWidgetTaskId="";if(getIntent()!=null&&getIntent().getBooleanExtra("plannerEstimateKnown",false)){try{int value=getIntent().getIntExtra("plannerEstimateMinutes",-1);task.put("estimateMinutes",value<1?JSONObject.NULL:value);}catch(Exception ignored){}}final JSONObject targetTask=task;new HandlerOnce().run(()->openTaskForm(targetTask,false));}}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(intent!=null&&intent.hasExtra(ChatNotifications.EXTRA_TASK))new HandlerOnce().run(()->openNotifiedChat(intent.getStringExtra(ChatNotifications.EXTRA_TASK)));setIntent(intent);if(intent!=null&&ACTION_TIMER_NOTIFICATION_PERMISSION.equals(intent.getAction())){new HandlerOnce().run(this::requestTimerNotificationPermission);return;}if(intent!=null&&AdibFloatingTimerService.ACTION_PERMISSION.equals(intent.getAction())){new HandlerOnce().run(this::showFloatingTimerPermission);return;}if(intent!=null&&(ACTION_QUICK_ADD.equals(intent.getAction())||(intent.getAction()!=null&&intent.getAction().startsWith("com.adib.maintenance.WIDGET_")))){applyWidgetNavigation(intent);if(finishAfterCalendarTask)renderCalendarTaskHost();else render();processPendingWidgetNavigation();refresh(true);if(ACTION_QUICK_ADD.equals(intent.getAction()))new HandlerOnce().run(()->openTaskForm(null,true));if(ACTION_WIDGET_PLUS.equals(intent.getAction()))new HandlerOnce().run(this::showPlusQuickAdd);if(ACTION_QUICK_EXPAND.equals(intent.getAction()))new HandlerOnce().run(this::openExpandedQuickTask);}else refresh(false);}
